```c
#include <stdio.h>

#define MAX 50

int adj[MAX][MAX];  // adjacency matrix
int visited[MAX];
int queue[MAX];
int front = 0, rear = 0;

void enqueue(int v) {
    queue[rear++] = v;
}

int dequeue() {
    return queue[front++];
}

int isEmpty() {
    return front == rear;
}

void BFS(int start, int n) {
    for (int i = 0; i < n; i++)
        visited[i] = 0;  // mark all as unvisited

    visited[start] = 1;
    enqueue(start);

    printf("BFS Traversal: ");

    while (!isEmpty()) {
        int u = dequeue();
        printf("%d ", u);

        for (int v = 0; v < n; v++) {
            if (adj[u][v] && !visited[v]) {
                visited[v] = 1;
                enqueue(v);
            }
        }
    }
}

int main() {
    int n, e;
    printf("Enter number of vertices and edges: ");
    scanf("%d %d", &n, &e);

    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            adj[i][j] = 0;

    printf("Enter %d edges (u v):\n", e);
    for (int i = 0; i < e; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        adj[u][v] = adj[v][u] = 1; // undirected graph
    }

    int start;
    printf("Enter start node: ");
    scanf("%d", &start);

    BFS(start, n);
    return 0;
}
